'use strict';
window.RCText=(()=>{
const fonts=[{"name": "RC Racing", "data": ""}, {"name": "RC Russo", "data": ""}, {"name": "RC Signature", "data": ""}];
const styles=[
{id:'logo_racing',name:'Logo · Racing',font:'RC Racing'},
{id:'logo_contour',name:'Logo · Doble contorno',font:'RC Russo'},
{id:'logo_shield',name:'Logo · Escudo',font:'RC Russo'},
{id:'logo_metal',name:'Logo · Metalizado',font:'RC Racing'},
{id:'logo_signature',name:'Logo · Firma',font:'RC Signature'},
{id:'logo_plate',name:'Logo · Placa',font:'RC Russo'}];
const map=new Map(styles.map(s=>[s.id,s]));let failure=null;
const loaded=Promise.all(fonts.map(async f=>{const face=new FontFace(f.name,`url(data:font/ttf;base64,${f.data})`);await face.load();document.fonts.add(face);})).catch(e=>{failure=e;});
async function ready(){await loaded;if(failure)throw Error('No se pudieron cargar las tipografías de logo. Usa el paquete completo.');}
function draw(ctx,s,w,h){
 const style=map.get(s.variant);if(!style)return;
 const label=String(s.text||'TU NOMBRE').trim()||'TU NOMBRE',p=s.color||'#171a22',a=s.accent||'#ee2233';
 ctx.save();ctx.shadowColor='transparent';ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;ctx.lineJoin='round';ctx.textAlign='center';ctx.textBaseline='alphabetic';
 // Fit the actual glyph extents (including script swashes), reserving room for outlines.
 let lo=1,hi=h*.78,size=lo,m;
 for(let i=0;i<18;i++){const n=(lo+hi)/2;ctx.font=`400 ${n}px "${style.font}"`;const q=ctx.measureText(label);const ww=q.actualBoundingBoxLeft+q.actualBoundingBoxRight,hh=q.actualBoundingBoxAscent+q.actualBoundingBoxDescent;if(ww<=w*.76&&hh<=h*.53){lo=n;size=n;}else hi=n;}
 ctx.font=`400 ${size}px "${style.font}"`;m=ctx.measureText(label);
 const x=(m.actualBoundingBoxLeft-m.actualBoundingBoxRight)/2,y=(m.actualBoundingBoxAscent-m.actualBoundingBoxDescent)/2;
 function text(fill,stroke,th,dx=0,dy=0){if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=th;ctx.strokeText(label,x+dx,y+dy);}if(fill){ctx.fillStyle=fill;ctx.fillText(label,x+dx,y+dy);}}
 function shape(points,fill,stroke=null,line=0){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(const q of points.slice(1))ctx.lineTo(q[0],q[1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.stroke();}}
 const stroke=Math.max(.4,h*.06);
 if(s.variant==='logo_shield'){
  shape([[-w*.47,-h*.4],[w*.47,-h*.4],[w*.43,h*.28],[0,h*.47],[-w*.43,h*.28]],p,a,h*.035);text('#ffffff',a,stroke*.6);shape([[-w*.32,h*.31],[w*.32,h*.31],[w*.27,h*.37],[-w*.27,h*.37]],a);
 }else if(s.variant==='logo_plate'){
  shape([[-w*.46,-h*.37],[w*.49,-h*.37],[w*.43,h*.36],[-w*.49,h*.36]],p,a,h*.04);
  text('#ffffff',a,stroke*.6);for(let i=0;i<3;i++)shape([[-w*.46+i*w*.06,-h*.45],[-w*.42+i*w*.06,-h*.45],[-w*.44+i*w*.06,-h*.4],[-w*.48+i*w*.06,-h*.4]],a);
 }else if(s.variant==='logo_signature'){
  text(p,a,stroke*1.5);text(p,'#ffffff',stroke*.7);ctx.strokeStyle=a;ctx.lineWidth=h*.035;ctx.beginPath();ctx.moveTo(-w*.41,h*.35);ctx.bezierCurveTo(-w*.2,h*.23,w*.19,h*.42,w*.45,h*.19);ctx.stroke();
 }else if(s.variant==='logo_metal'){
  text(null,p,stroke*1.8);text(null,a,stroke*.9);const grad=ctx.createLinearGradient(0,-h*.3,0,h*.3);for(const [stop,col] of [[0,'#ffffff'],[.25,'#d9e4f4'],[.48,'#ffffff'],[.51,'#48556b'],[.78,'#eaf2ff'],[1,'#8293ad']])grad.addColorStop(stop,col);text(grad,null,0);shape([[-w*.39,h*.34],[w*.43,h*.34],[w*.36,h*.41],[-w*.42,h*.41]],a);
 }else if(s.variant==='logo_contour'){
  text(null,p,stroke*2.1,w*.009,h*.024);text(null,a,stroke*1.65);text(null,'#ffffff',stroke*.9);text(p,null,0);
 }else{
  for(let i=0;i<3;i++)shape([[-w*.45+i*w*.06,-h*.25],[-w*.43+i*w*.06,-h*.25],[-w*.47+i*w*.06,h*.14],[-w*.49+i*w*.06,h*.14]],a);
  ctx.save();ctx.transform(1,0,-.12,1,0,0);text(null,p,stroke*2,w*.014,h*.025);text(null,a,stroke*1.5);text(null,'#ffffff',stroke*.75);text(p,null,0);ctx.restore();
  shape([[-w*.4,h*.33],[w*.45,h*.26],[w*.37,h*.4],[-w*.45,h*.44]],a);
 }
 ctx.restore();
}
return Object.freeze({styles,has:id=>map.has(id),ready,draw});
})();
